# bottom-row configuration score in the opening, centre column still (nearly) empty
W_ME = [-1.0, 1.5, 0.3, 0.0, -0.5, 1.5, -1.0]
W_TH = [0.0, -1.0, 0.0, 0.0, 0.3, -1.0, 1.5]

def score(b):
    if b.ply < 3 or b.ply > 16 or b.heights[3] > 1:
        return -9.0
    s = 2.0 if b.heights[3] == 0 else 1.0
    row = b.grid[0]
    for c in range(7):
        if c == 3:
            continue
        if row[c] == 1:
            s += W_ME[c]
        elif row[c] == 2:
            s += W_TH[c]
    return s

def fires(b):
    return score(b) >= 3.5

def level(b):
    s = score(b)
    if s < 2.0:
        return 0
    return max(0, min(9, int(round((s - 2.0) * 2.5))))

# my bottom-row stone in column 1 or 5 supported by a second feature next to it
def parts(b):
    g = b.grid
    n = 0
    # left: my stone at (0,1) together with my (0,2) or their stone on top (1,1)
    if g[0][1] == 1 and (g[0][2] == 1 or g[1][1] == 2):
        n += 1
    # right: my stone at (0,5) together with my (0,4) or their stone on top (1,5)
    if g[0][5] == 1 and (g[0][4] == 1 or g[1][5] == 2):
        n += 1
    return n

def fires(b):
    return parts(b) >= 1

def level(b):
    n = parts(b)
    if n == 0:
        return 0
    s = 4 + 2 * (n - 1)
    if b.heights[3] <= 1:
        s += 2
    if b.ply <= 12:
        s += 1
    return min(9, s)

# hand-weighted bottom-row pattern score (opening): centre column empty, my stones on (0,1)/(0,5)
# extended by my neighbour (0,2)/(0,4) or capped by their stone, their stone in the right corner (0,6)
def score(b):
    if b.ply < 3:
        return -9.0
    g = b.grid
    r0, r1 = g[0], g[1]
    s = 0.0
    if b.heights[3] == 0:
        s += 1.5
    elif b.heights[3] == 1:
        s += 0.5
    if r0[1] == 1:
        s += 1.0
        if r0[2] == 1:
            s += 2.0
        if r1[1] == 2:
            s += 1.0
    if r0[5] == 1:
        s += 1.0
        if r0[4] == 1:
            s += 1.5
        if r1[5] == 2:
            s += 1.5
    if r0[6] == 2:
        s += 1.0
        if r1[6] == 1:
            s += 0.5
    if r0[0] == 1:
        s -= 1.5
    elif r0[0] == 2:
        s -= 0.5
    if r0[1] == 2:
        s -= 1.0
    if r0[5] == 2:
        s -= 1.0
    if r0[6] == 1:
        s -= 0.5
    if b.ply > 16:
        s -= 1.5
    return s

def fires(b):
    return score(b) >= 3.0

def level(b):
    s = score(b)
